class BtsCertificatesPage(pages.configuration.BtsCertificatesPage):

    def __init__(self, driver):
        super(BtsCertificatesPage, self).__init__(driver)
        self._view_panel = BtsCertificatesPageViewPanel(driver)


class BtsCertificatesPageViewPanel(pages.configuration.BtsCertificatesPageViewPanel):
    _BTS_TRUST_CHAIN_HIDDEN_BUTTON_SCRIPT = ('div[class="install-cert-row"] p-fileupload[accept=".p12"] '
                                             'input[type="file"]')
    _ADDITIONAL_CA_CERTIFICATES_HIDDEN_BUTTON_SCRIPT = ('div[class="install-cert-row"] p-fileupload'
                                                        '[accept=".pem,.der,.crt,.cer"] input[type="file"]')
    _BTS_TRUST_CHAIN_BUTTON_XPATH = '//span[contains(text(), "Browse")]/../..//input[@type="file"][@accept=".p12"]'
    _ADDITIONAL_CA_CERTIFICATES_BUTTON_XPATH = ('//span[contains(text(), "Browse")]/../..//input[@type="file"]'
                                                '[@accept=".pem,.der,.crt,.cer"]')
    _INSTALL_BUTTON_XPATH = '//button[*[contains(text(), "Install")]]'
    _INSTALL_CERTIFICATES_INFO_SUCCESS_XPATH = '//*[@class="install-cert"]//*[contains(@class, "icon-ok")]'
    _INSTALL_CERTIFICATES_INFO_SUCCESS_TEXT = "Certificates installation completed"
    _INSTALL_CERTIFICATES_INFO_ERROR_XPATH = ("//div[@class='install-status-group']/div"
                                              "/span[contains(@class, 'install-cert-error-msg')]")
    _CERTIFICATE_CHOOSE_XPATH = '//bts-certificates//tr[td[contains(text(), "{}")]]/td[1]//div[@*="checkbox"]'
    _DELETE_BUTTON_XPATH = '//bts-certificates-delete//button[*[contains(text(), "Delete")]]'
    _DELETE_COMPLETED_INFO = '//bts-certificates-delete//*[contains(text(), "Certificates deletion completed")]'

    def __int__(self, driver):
        super(BtsCertificatesPageViewPanel, self).__init__(driver)

    def delete_certificate(self, serial_numbers, timeout=60):
        if not isinstance(serial_numbers, list):
            raise AttributeError('The param serial_numbers should be type of list.')

        for serial_number in serial_numbers:
            self.click_element_by_xpath(self._CERTIFICATE_CHOOSE_XPATH.format(serial_number))
        self.click_element_by_xpath(self._DELETE_BUTTON_XPATH)

        delete_certificate_modal = DeleteCertificateModal(self.driver)
        delete_certificate_modal._MODAL_XPATH = '//div[@*="dialog"]'
        delete_certificate_modal._DELETE_BUTTON = '//div[@*="dialog"]//button[*[contains(text(), "Delete")]]'
        delete_certificate_modal.wait_for_delete_certificate_modal_appear(timeout)
        delete_certificate_modal.delete(timeout)

        self.wait_for_visibility_by_xpath(self._DELETE_COMPLETED_INFO)

    def install_bts_certificates_from_local(self, bts_file_path, password, additional_ca_file_path, timeout):
        try:
            if bts_file_path:
                self.load_file_from_hidden_button_in_gnb(self._BTS_TRUST_CHAIN_HIDDEN_BUTTON_SCRIPT,
                                                         self._BTS_TRUST_CHAIN_BUTTON_XPATH, bts_file_path,
                                                         timeout)
            if password is not None:
                self.insert_text_to_enable_element((By.XPATH, self._BTS_TRUST_CHAIN_PASSWORD_INPUT_XPATH), password,
                                                   timeout)
            if additional_ca_file_path:
                self.load_file_from_hidden_button_in_gnb(self._ADDITIONAL_CA_CERTIFICATES_HIDDEN_BUTTON_SCRIPT,
                                                         self._ADDITIONAL_CA_CERTIFICATES_BUTTON_XPATH,
                                                         additional_ca_file_path,
                                                         timeout)
            self.click_enabled_element((By.XPATH, self._INSTALL_BUTTON_XPATH), timeout)
            self.wait_for_visibility_by_xpath(self._INSTALL_CERTIFICATES_INFO_SUCCESS_XPATH, timeout)
            return self._INSTALL_CERTIFICATES_INFO_SUCCESS_TEXT
        except TimeoutException:
            error_text = self.get_text_by_xpath(self._INSTALL_CERTIFICATES_INFO_ERROR_XPATH)
            return error_text if error_text else None


