class VendorCertificatesPage(pages.configuration.VendorCertificatesPage):
    _SN_CERTIFICATES_XPATH = "//vendor-certificates//tbody/tr/td[7]"

    def __init__(self, driver):
        super(VendorCertificatesPage, self).__init__(driver)
        self._view_panel = VendorCertificatesPageViewPanel(driver)
        self._detail_panel = VendorCertificatesPageDetailPanel(driver)

    def _get_detail_panel_info_vendor(self, element):
        self._detail_panel.expand_details_panel()
        element.click()
        return self._detail_panel.get_certificate_details_info()

    def _get_certificates_vendor(self):
        cert_info = {}
        cert_elements = self._view_panel.driver.find_elements_by_xpath(self._SN_CERTIFICATES_XPATH)
        for element in cert_elements:
            single_cert_info = dict()
            try:
                element_serial_number = element.text.strip()
            except NoSuchElementException:
                element_serial_number = None
            if element_serial_number:
                single_cert_info[element_serial_number] = self._get_detail_panel_info_vendor(element)
                cert_info.update(single_cert_info)
        return cert_info

    def get_certificates_vendor(self, serial_number, timeout):
        cert_vendor_info = {}
        try:
            self._view_panel.expand_certificates_list_vendor(timeout)
        except TimeoutException:
            logging.warning("No certificate is found.")
            return cert_vendor_info

        cert_vendor_info.update(self._get_certificates_vendor())

        if serial_number in cert_vendor_info.keys():
            return {serial_number: cert_vendor_info[serial_number]}
        return cert_vendor_info

    def restore_vendor_certificates(self, timeout_for_restore):
        return self._view_panel.restore_vendor_certificates(timeout_for_restore)


class VendorCertificatesPageViewPanel(pages.configuration.VendorCertificatesPageViewPanel):
    _EXPAND_CERTIFICATES_XPATH = ("//vendor-certificates//button[@aria-label='Expand all'] "
                                  "| //vendor-certificates//p-button[@title='Expand all']")
    _RESTORE_VENDOR_CERTIFICATES_XPATH = '//vendor-certificates//*[@*="Restore Vendor Certificates"]'
    _RESTORE_VENDOR_CERTIFICATES_ON_PROCESS_XPATH = '//vendor-certificates//span[contains(@class, "icon spinner")]'
    _RESTORE_VENDOR_CERTIFICATES_RESULT_XPATH = "//vendor-certificates//ui-inline-info"

    def __init__(self, driver):
        super(VendorCertificatesPageViewPanel, self).__init__(driver)

    def restore_vendor_certificates(self, timeout_for_restore):
        self.wait_for_visibility_by_xpath(self._RESTORE_VENDOR_CERTIFICATES_XPATH, timeout=timeout_for_restore)
        self.click_enabled_element((By.XPATH, self._RESTORE_VENDOR_CERTIFICATES_XPATH), timeout=timeout_for_restore)
        restore_vendor_modal = RestoreVendorCertificateModal(self.driver)
        restore_vendor_modal._MODAL_XPATH = '//div[@*="dialog"]'
        restore_vendor_modal._RESTORE_BUTTON = '//div[@*="dialog"]//button[*[contains(text(), "Restore")]]'
        restore_vendor_modal.wait_for_restore_vendor_certificates_modal_appear(timeout_for_restore)
        restore_vendor_modal.restore(timeout=timeout_for_restore)
        self.wait_until_element_is_invisible(self._RESTORE_VENDOR_CERTIFICATES_ON_PROCESS_XPATH,
                                             timeout=timeout_for_restore)
        return self.get_text_by_xpath(self._RESTORE_VENDOR_CERTIFICATES_RESULT_XPATH, timeout=timeout_for_restore)


class CertificatesPageDetailPanel(DetailPanel):
    _DETAILS_TABLES_XPATH = '//certificate-details//table[@class="details-table"]'
    _DETAILS_TABLE_XPATH = _DETAILS_TABLES_XPATH + '[{index}]'
    _DETAILS_TABLE_TITLE_XPATH = _DETAILS_TABLE_XPATH + '/preceding-sibling::div[1][contains(@class, "divider")]'
    _DETAILS_KEY_XPATH = "//tr[count(*)=2]/th"
    _DETAILS_VALUE_XPATH = "//tr[count(*)=2]/td"

    def __init__(self, driver):
        super(CertificatesPageDetailPanel, self).__init__(driver)

    def _get_certificate_details_table_dict(self, table_xpath):
        return self.get_dict_from_elements_by_xpath(table_xpath + self._DETAILS_KEY_XPATH,
                                                    table_xpath + self._DETAILS_VALUE_XPATH,
                                                    ':')

    def _get_certificate_details_table_title(self, title_xpath):
        try:
            table_title = self.driver.find_element_by_xpath(title_xpath).text
        except NoSuchElementException:
            table_title = None
        return table_title

    def get_certificate_details_info(self):
        """
        Get certificate details info on the details panel.
        :return: dict
        """
        info = dict()
        details_tables = self.driver.find_elements_by_xpath(self._DETAILS_TABLES_XPATH)
        for index in range(len(details_tables)):
            table_xpath = self._DETAILS_TABLE_XPATH.format(index=index + 1)
            table_dict = self._get_certificate_details_table_dict(table_xpath)

            table_title = None
            if index > 0:
                table_title = self._get_certificate_details_table_title(
                    self._DETAILS_TABLE_TITLE_XPATH.format(index=index + 1))

            if table_title and not table_dict:
                info.update({table_title: {}})
            elif table_title and table_dict:
                info.update({table_title: table_dict})
            else:
                info.update(table_dict)
        return info


class VendorCertificatesPageDetailPanel(CertificatesPageDetailPanel):

    def __init__(self, driver):
        super(VendorCertificatesPageDetailPanel, self).__init__(driver)
